    /**
     * Procesar diff para mostrar en CKEditor con colores
     */
    private function processDiffForCKEditor($diffData, $oldContent, $newContent) {
        $result = '';
        
        // Depurar estructura del JSON
        //error_log("Estructura del diff JSON: " . print_r($diffData, true));
        
        foreach ($diffData as $blockIndex => $block) {
            // Verificar si el bloque tiene la estructura correcta
            if (!isset($block['lines']) || !is_array($block['lines'])) {
                error_log("Bloque $blockIndex no tiene estructura 'lines' válida");
                continue;
            }
            
            foreach ($block['lines'] as $lineIndex => $line) {
                // Verificar estructura de cada línea
                if (!isset($line['type']) || !isset($line['content'])) {
                    // Intentar con diferentes estructuras posibles
                    if (isset($line['tag'])) {
                        $lineType = $this->mapTagToType($line['tag']);
                        $lineContent = $line['content'] ?? $line['line'] ?? '';
                    } else {
                        error_log("Línea $lineIndex en bloque $blockIndex no tiene estructura válida: " . print_r($line, true));
                        continue;
                    }
                } else {
                    $lineType = $line['type'];
                    $lineContent = $line['content'];
                }
                
                // Procesar según el tipo de línea
                switch ($lineType) {
                    case 'unmodified':
                    case 'unchanged':
                    case 'equal':
                        $result .= '<p class="diff-unchanged">' . $this->cleanContentForCKEditor($lineContent) . '</p>';
                        break;
                        
                    case 'deleted':
                    case 'delete':
                    case '-':
                        $result .= '<p class="diff-deleted" style="background-color: #ffe6e6; text-decoration: line-through; color: #cc0000;">' . 
                                $this->cleanContentForCKEditor($lineContent) . '</p>';
                        break;
                        
                    case 'inserted':
                    case 'insert':
                    case '+':
                        $result .= '<p class="diff-inserted" style="background-color: #e6ffe6; color: #006600;">' . 
                                $this->cleanContentForCKEditor($lineContent) . '</p>';
                        break;
                        
                    default:
                        $result .= '<p class="diff-unknown">' . $this->cleanContentForCKEditor($lineContent) . '</p>';
                        break;
                }
            }
        }
        
        return $result ?: $this->generateSimpleDiffForCKEditor($oldContent, $newContent);
    }

